"use client";

import * as React from "react";
import { Bell } from "lucide-react";
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/**
 * NotificationCenter — a bell trigger opening a popover list of
 * read/unread items with a "mark all read" action. Composed directly
 * from `Popover` (re-exported as the root — no new open-state logic)
 * and `Button`; `NotificationItem` follows `ListItem`'s interactive-row
 * convention. `unreadCount`/`unread`/`onMarkAllRead` are plain props —
 * the read-state itself stays the caller's, same as every other
 * controlled/stateless component in this library. Gap-fill addition
 * (not in the original Figma source).
 */
const NotificationCenter = Popover;

export interface NotificationCenterTriggerProps extends React.ComponentPropsWithoutRef<typeof Button> {
  unreadCount?: number;
}

const NotificationCenterTrigger = React.forwardRef<HTMLButtonElement, NotificationCenterTriggerProps>(
  ({ className, unreadCount = 0, children, ...props }, ref) => (
    <PopoverTrigger asChild>
      <Button
        ref={ref}
        variant="Ghost"
        size="icon"
        aria-label={unreadCount > 0 ? `Notifications, ${unreadCount} unread` : "Notifications"}
        className={cn("relative", className)}
        {...props}
      >
        {children ?? <Bell className="size-5" />}
        {unreadCount > 0 && (
          <span className="absolute right-1.5 top-1.5 flex size-2 rounded-full bg-destructive ring-2 ring-background" />
        )}
      </Button>
    </PopoverTrigger>
  ),
);
NotificationCenterTrigger.displayName = "NotificationCenterTrigger";

export interface NotificationCenterContentProps extends React.ComponentPropsWithoutRef<typeof PopoverContent> {
  onMarkAllRead?: () => void;
}

const NotificationCenterContent = React.forwardRef<HTMLDivElement, NotificationCenterContentProps>(
  ({ className, onMarkAllRead, children, align = "end", ...props }, ref) => (
    <PopoverContent ref={ref} align={align} className={cn("w-80 p-0", className)} {...props}>
      <div className="flex items-center justify-between border-b border-border px-4 py-3">
        <p className="text-title-sm font-medium text-foreground">Notifications</p>
        {onMarkAllRead && (
          <button
            type="button"
            onClick={onMarkAllRead}
            className="text-label-md font-medium text-link outline-none hover:underline focus-visible:underline"
          >
            Mark all read
          </button>
        )}
      </div>
      <div className="flex max-h-80 flex-col divide-y divide-border overflow-y-auto">{children}</div>
    </PopoverContent>
  ),
);
NotificationCenterContent.displayName = "NotificationCenterContent";

export interface NotificationItemProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title: React.ReactNode;
  description?: React.ReactNode;
  time?: React.ReactNode;
  unread?: boolean;
  onSelect?: () => void;
}

const NotificationItem = React.forwardRef<HTMLDivElement, NotificationItemProps>(
  ({ className, title, description, time, unread, onSelect, ...props }, ref) => {
    const interactive = !!onSelect;
    return (
      <div
        ref={ref}
        role={interactive ? "button" : undefined}
        tabIndex={interactive ? 0 : undefined}
        onClick={onSelect}
        onKeyDown={
          interactive
            ? (e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onSelect?.();
                }
              }
            : undefined
        }
        className={cn(
          "flex items-start gap-3 px-4 py-3 font-sans outline-none",
          interactive && "cursor-pointer hover:bg-accent focus-visible:bg-accent",
          className,
        )}
        {...props}
      >
        <span className={cn("mt-1.5 size-2 shrink-0 rounded-full", unread ? "bg-action" : "bg-transparent")} />
        <div className="min-w-0 flex-1">
          <p className={cn("truncate text-body-sm", unread ? "font-medium text-foreground" : "text-muted-foreground")}>
            {title}
          </p>
          {description && <p className="truncate text-body-sm text-muted-foreground">{description}</p>}
          {time && <p className="mt-0.5 text-label-sm text-muted-foreground">{time}</p>}
        </div>
      </div>
    );
  },
);
NotificationItem.displayName = "NotificationItem";

export { NotificationCenter, NotificationCenterTrigger, NotificationCenterContent, NotificationItem };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
